files.menus/sized.yaml:
schema: menu/v1
id: sized
size: 27
title:
  - kind: text
    value: "Day"
    x: 8
    y: 20
    size: 12
  - { kind: text, value: floor, y: -50, size: 16 }
  - { kind: text, value: cap, y: 500.9, size: 24 }
  - { kind: text, value: "bad size", y: 40, size: 10 }
  - { kind: text, value: "size as text", y: 41, size: "12" }
  - { kind: text, value: "no y", size: 32 }
  - { kind: text, value: "fraction", y: 30.7, size: 12.9 }
  - { kind: text, value: "y as text", y: "33", size: 20 }
  - kind: textarea
    value: "lines"
    y: 150
    size: 12
    line_height: 9
  - { kind: textarea, value: above, y: -19, size: 12, line_height: 80 }
  - { kind: textarea, value: "default line height", y: 160, size: 20 }
  - { kind: textarea, value: "line height 0", y: 170, size: 16, line_height: 0 }
  - { kind: textarea, value: below, y: 173, size: 32 }
  - { kind: glyph, asset: none, y: 77 }
  - plain
elements:
  - id: freezes
    positions: "7-8"
    label: { text: "{a}/{b}", size: 12, offset_y: 3 }
    states:
      - if: [{ expression: x }]
        label: { text: Claim, size: 16, offset_y: -2.5 }
      - label: "not a map"
  - id: tall
    positions: "0-1,9-10"
    label: { text: big, size: 32 }
  - id: rows
    positions: "18-26"
    iterates: { source: days }
    label: { text: no, size: 24 }
  - id: broken
    positions: "3,5"
    label: { text: no, size: 24 }

